{'tracks': [{'id': 't1', 'title': 'Song A'}, {'id': 't2', 'title': 'Funny Clip'}], 'thumbnails': [{'id': 'h1', 'label': 'Funny'}, {'id': 'h2', 'label': 'Music'}], 'interactions': [{'trackId': 't1', 'thumbId': 'h1', 'plays': 100, 'clicks': 10}, {'trackId': 't1', 'thumbId': 'h2', 'plays': 80, 'clicks': 20}, {'trackId': 't2', 'thumbId': 'h1', 'plays': 50, 'clicks': 5}, {'trackId': 't2', 'thumbId': 'h2', 'plays': 60, 'clicks': 30}], 'k': 2}

Return the output dict as a json inside a json with the key 'code_output'. Here is the code:

```js
import { compareTwoStrings } from 'string-similarity';
import * as math from 'mathjs';
export function generateSequence(input) {
  const tracks = input.tracks || [];
  const thumbs = input.thumbnails || [];
  const interactions = input.interactions || [];
  const k = input.k != null ? input.k : Math.min(tracks.length, thumbs.length);
  const nT = tracks.length, nH = thumbs.length;
  const M = Array.from({ length: nT }, () => Array(nH).fill(0));
  for (let i = 0; i < nT; i++) for (let j = 0; j < nH; j++) M[i][j] = compareTwoStrings(tracks[i].title, thumbs[j].label);
  const C = Array.from({ length: nH }, () => Array(nT).fill(0));
  for (const it of interactions) {
    const ti = tracks.findIndex(t => t.id === it.trackId);
    const hj = thumbs.findIndex(h => h.id === it.thumbId);
    if (ti >= 0 && hj >= 0 && it.plays > 0) C[hj][ti] = it.clicks / it.plays;
  }
  const A = math.matrix(M), B = math.matrix(C);
  const TT = math.multiply(A, B);
  const TT2 = math.multiply(B, A);
  let x = math.ones(nT), y = math.ones(nH);
  for (let it = 0; it < 20; it++) {
    x = math.multiply(TT, x);
    const mx = math.max(x) || 1;
    x = math.divide(x, mx);
    y = math.multiply(TT2, y);
    const my = math.max(y) || 1;
    y = math.divide(y, my);
  }
  const xArr = x._data || x;
  const yArr = y._data || y;
  const trackRanking = tracks.map((t, i) => ({ id: t.id, score: xArr[i] }))
    .sort((a, b) => b.score - a.score)
    .map(o => o.id);
  const thumbRanking = thumbs.map((h, j) => ({ id: h.id, score: yArr[j] }))
    .sort((a, b) => b.score - a.score)
    .map(o => o.id);
  const sequence = [];
  for (let i = 0; i < k; i++) {
    if (trackRanking[i]) sequence.push({ type: 'track', id: trackRanking[i] });
    if (thumbRanking[i]) sequence.push({ type: 'thumb', id: thumbRanking[i] });
  }
  return { sequence, trackRanking, thumbRanking };
}
