```python
def is_strongly_connected(edges: list[tuple[int, int]]) -> bool:
    if not edges:
        return True

    vertices = set()
    for u, v in edges:
        vertices.add(u)
        vertices.add(v)

    if not vertices:
        return True

    num_vertices = len(vertices)

    def reachable(start_node):
        visited = set()
        queue = [start_node]
        visited.add(start_node)

        while queue:
            node = queue.pop(0)
            for u, v in edges:
                if u == node and v not in visited:
                    visited.add(v)
                    queue.append(v)
        return visited

    start_node = next(iter(vertices))
    reachable_from_start = reachable(start_node)

    if len(reachable_from_start) != num_vertices:
        return False

    reversed_edges = [(v, u) for u, v in edges]

    def reachable_reversed(start_node):
        visited = set()
        queue = [start_node]
        visited.add(start_node)

        while queue:
            node = queue.pop(0)
            for u, v in reversed_edges:
                if u == node and v not in visited:
                    visited.add(v)
                    queue.append(v)
        return visited

    reachable_to_start = reachable_reversed(start_node)

    return len(reachable_to_start) == num_vertices
