import ast
import operator

def calculate(expression):
    """Safely evaluates a mathematical expression."""

    ops = {ast.Add: operator.add,
           ast.Sub: operator.sub,
           ast.Mult: operator.mul,
           ast.Div: operator.truediv}

    def eval_expr(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            op = ops[type(node.op)]
            return op(eval_expr(node.left), eval_expr(node.right))
        elif isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.USub):
                return -eval_expr(node.operand)
            else:
                raise TypeError("Unsupported unary operator")
        elif isinstance(node, ast.NameConstant):
            return node.value
        else:
            raise TypeError("Unsupported node type")

    return eval_expr(ast.parse(expression, mode='eval').body)

if __name__ == "__main__":
