def bfs(graph, start_node):
    visited = []
    queue = [start_node]
    visited_set = {start_node}

    while queue:
        node = queue.pop(0)
        visited.append(node)

        neighbors = graph.get(node, [])
        for neighbor in neighbors:
            if neighbor not in visited_set:
                queue.append(neighbor)
                visited_set.add(neighbor)

    return " ".join(visited)

