import math

def mathematical_puzzle_solver(data):
    def process_integer(n, depth=0):
        if n == 0:
            return 0
        if depth > 2:
            return n

        factors = [i for i in range(1, min(abs(n) + 1, 64)) if n % i == 0]
        prime_factors = [f for f in factors if is_prime(f)]

        digit_sum = sum(int(d) for d in str(abs(n)))

        # Calculate special sequence based on factors
        sequence = []
        for i, f in enumerate(factors[:5]):
            if i % 2 == 0:
                sequence.append(f * digit_sum)
            else:
                sequence.append(f + digit_sum)

        core_value = sum(prime_factors) * math.gcd(abs(n), digit_sum)

        # Recursive component for depth
        if depth < 2 and len(factors) > 1:
            mid_factor = factors[len(factors) // 2]
            core_value += process_integer(mid_factor, depth + 1)

        return core_value % 1000

    def process_string(s):
        if not s:
            return {"value": 0}

        char_values = [ord(c) for c in s]
        sum_value = sum(char_values)
        product_value = 1
        for cv in char_values:
            product_value = (product_value * cv) % 1000

        alpha_count = sum(c.isalpha() for c in s)
        digit_count = sum(c.isdigit() for c in s)

        cipher_text = ""
        for i, c in enumerate(s):
            if c.isalpha():
                base = ord('A') if c.isupper() else ord('a')
                shifted = (ord(c) - base + i + alpha_count) % 26
                cipher_text += chr(base + shifted)
            elif c.isdigit():
                cipher_text += str((int(c) + digit_count) % 10)
            else:
                cipher_text += c

        return {
            "cipher": cipher_text,
            "value": (sum_value * product_value) % 1000
        }

    def process_list(items):
        if not items:
            return {"result": []}

        processed = []
        for i, item in enumerate(items[:10]):  # Limit to first 10 items
            if isinstance(item, dict):
                processed.append(process_dict(item))
            elif isinstance(item, list):
                processed.append(process_list(item))
            elif isinstance(item, int):
                processed.append(process_integer(item))
            elif isinstance(item, str):
                processed.append(process_string(item))
            else:
                processed.append(0)

        # Calculate aggregates for numerical values
        numeric_values = [p for p in processed if isinstance(p, int)]
        if numeric_values:
            return {
                "result": processed,
                "sum": sum(numeric_values),
                "product": math.prod(numeric_values) % 1000
            }
        return {"result": processed}

    def process_dict(d):
        if not d:
            return {"value": 0}

        result = {}
        # Process up to 10 key-value pairs
        for k, v in sorted(list(d.items())[:10]):
            if isinstance(v, dict):
                result[k] = process_dict(v)
            elif isinstance(v, list):
                result[k] = process_list(v)
            elif isinstance(v, int):
                result[k] = process_integer(v)
            elif isinstance(v, str):
                result[k] = process_string(v)

        # Calculate metadata
        key_lengths = [len(str(k)) for k in d.keys()]
        result["meta"] = {
            "key_count": len(d),
            "avg_key_length": sum(key_lengths) // max(1, len(key_lengths)),
            "complexity": (len(d) * sum(key_lengths)) % 100
        }
        return result

    # Main dispatch based on input type
    if isinstance(data, dict):
        return process_dict(data)
    elif isinstance(data, list):
        return process_list(data)
    elif isinstance(data, int):
        return {"result": process_integer(data)}
    elif isinstance(data, str):
        return process_string(data)
    else:
        return {"error": "Unsupported data type"}

