export function allocateReservations({tables:tbs,requests:rqs}){
  const Z=tbs.map((t,i)=>({...t,i}));
  const tM=s=>(d=>d.getHours()*60+d.getMinutes())(new Date(s));
  const Q=rqs.map((r,i)=>{const S=tM(r.start),E=tM(r.end),L=Math.max(0,E-S),bs=L?((1n<<BigInt(L))-1n)<<BigInt(S):0n;return{...r,i,bs};});
  const C=Z.map(t=>t.capacity),M=Q.map(r=>Z.map((_,j)=>C[j]>=r.group));
  let BEST=[-1,Infinity,{}],CM=new Array(Z.length).fill(0n),AS={};
  (function _(i,c,w){
    if(i===Q.length){
      if(c>BEST[0]||(c===BEST[0]&&w<BEST[1]))BEST=[c,w,JSON.parse(JSON.stringify(AS))];
      return;
    }
    const R=Q[i];
    for(let j=0;j<Z.length;j++)if(M[i][j]&&!(CM[j]&R.bs)){
