def cholesky_factorization(matrix: List[List[float]]) -> List[List[float]]:
    n = len(matrix)
    lower = [[0.0] * n for _ in range(n)]

    for i in range(n):
        for j in range(i + 1):
            sum_val = sum(lower[i][k] * lower[j][k] for k in range(j))

            if i == j:
                lower[i][i] = (matrix[i][i] - sum_val)**0.5
            else:
                lower[i][j] = (matrix[i][j] - sum_val) / lower[j][j]

    return lower
