```python
def topoSort(V, adj):
    in_degree = [0] * V
    for i in range(V):
        for v in adj[i]:
            in_degree[v] += 1

    queue = []
    for i in range(V):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    count = 0
    while queue:
        u = queue.pop(0)
        result.append(u)
        count += 1

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if count != V:
        return []  # Cycle detected
    else:
        return result
