import java.util.Arrays;

class Solution {
    /**
     * Converts a 2D array of integers to a 1D array.
     *
     * @param twoDArray The non-empty 2D array to convert.
     * @return A 1D array containing all elements from the 2D array.
     */
    public int[] convertTo1D(int[][] twoDArray) {
        int rows = twoDArray.length;
        int cols = twoDArray[0].length;
        int[] oneDArray = new int[rows * cols];
        int index = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                oneDArray[index++] = twoDArray[i][j];
            }
        }

        return oneDArray;
    }

    public static void main(String[] args) {
        Solution solution = new Solution();

        int[][] test1 = {{1, 2, 3}, {4, 5, 6}};
        int[] result1 = solution.convertTo1D(test1);
        System.out.println("Test 1: " + Arrays.toString(result1)); // Expected: [1, 2, 3, 4, 5, 6]

        int[][] test2 = {{7}, {8}, {9}};
        int[] result2 = solution.convertTo1D(test2);
        System.out.println("Test 2: " + Arrays.toString(result2)); // Expected: [7, 8, 9]

        int[][] test3 = {{10, 11}, {12, 13}, {14, 15}};
