import re

def bigram_frequency(text):
    text = text.lower()
    text = re.sub(r'[^\w\s]', '', text)
    words = text.split()
    stop_words = {'a', 'an', 'the', 'and', 'or', 'if', 'but', 'is', 'in', 'on', 'at', 'to', 'of', 'with', 'for', 'by', 'that', 'this', 'from'}
    filtered_words = [word for word in words if word not in stop_words]
    bigrams = [(filtered_words[i], filtered_words[i+1]) for i in range(len(filtered_words) - 1)]
    frequency = {}
    for bigram in bigrams:
        if bigram in frequency:
            frequency[bigram] += 1
        else:
            frequency[bigram] = 1
    return frequency

if __name__ == "__main__":
    text = input()
    result = bigram_frequency(text)
    print(result)
