def conv_input_length(output_length: int, filter_size: int, padding: str, stride: int) -> int:
    if output_length is None:
        return None
    if padding == 'same':
        return (output_length - 1) * stride + filter_size - 2 * (filter_size // 2)
    elif padding == 'valid':
        return (output_length - 1) * stride + filter_size
    elif padding == 'full':
