class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

def insert(root, key):
    if root is None:
        return Node(key)
    if key < root.key:
        root.left = insert(root.left, key)
    else:
        root.right = insert(root.right, key)
    return root

def ceil_util(root, x, ceil):
    if root is None:
        return ceil
    if root.key == x:
        return root.key
    if root.key < x:
        return ceil_util(root.right, x, ceil)

    if ceil is None or root.key < ceil:
        ceil = root.key

    return ceil_util(root.left, x, ceil)

def find_ceil(root, x):
    ceil = None
    result = ceil_util(root, x, ceil)
    if result is None:
        return -1
    return result

