def longest_common_prefix_trie(strings):
    if not strings:
        return ""

    trie = {}
    for string in strings:
        node = trie
        for char in string:
            if char not in node:
                node[char] = {}
            node = node[char]

    prefix = ""
    node = trie
    while len(node) == 1 and node:
        char = next(iter(node))
        prefix += char
        node = node[char]

