def max_prime_divisor(n: int) -> int:
    if n < 2:
        return -1
    n = abs(n)
    largest_divisor = 1
    i = 2
    while i * i <= n:
        while n % i == 0:
            largest_divisor = i
            n //= i
        i += 1
    if n > 1:
        largest_divisor = n
    return largest_divisor
