def betterString(str1, str2):
    def distinctSubsequences(s):
        n = len(s)
        dp = [0] * (n + 1)
        dp[0] = 1
        last_occurrence = {}
        for i in range(1, n + 1):
            dp[i] = 2 * dp[i - 1]
            if s[i - 1] in last_occurrence:
                dp[i] -= dp[last_occurrence[s[i - 1]] - 1]
            last_occurrence[s[i - 1]] = i
        return dp[n]

    count1 = distinctSubsequences(str1)
    count2 = distinctSubsequences(str2)

    if count1 >= count2:
        return str1
    else:
        return str2
