Below is a piece of js code. Your job is to predict the output of the function processMatrix given an input, which is a json-serializable dict. Here is the input:

{'matrix': [[1, 2], [3, 4]]}

Return the output dict as a json inside a json with the key 'code_output'. Here is the code:

```js
import Fraction from "fraction.js";
export const processMatrix = (function(){
  const F = x => new Fraction(x);
  const swapRows = (M, i, j) => { [M[i], M[j]] = [M[j], M[i]]; };
  return function({ matrix: m }){
    const M = m.map(r => r.map(e => F(e)));
    const n = M.length;
    let detAcc = F(1);
    for(let i = 0; i < n; i++){
      // find pivot
      let pr = i;
      while(pr < n && M[pr][i].equals(0)) pr++;
      if(pr === n){ detAcc = F(0); break; }
      if(pr !== i){ swapRows(M, i, pr); detAcc = detAcc.neg(); }
      const pv = M[i][i];
      detAcc = detAcc.mul(pv);
      // normalize pivot row
      for(let cj = 0; cj < M[i].length; cj++){
        M[i][cj] = M[i][cj].div(pv);
      }
      // eliminate other rows
      for(let r = 0; r < n; r++){
        if(r === i) continue;
        const factor = M[r][i];
        for(let cj = i; cj < M[r].length; cj++){
          M[r][cj] = M[r][cj].sub(factor.mul(M[i][cj]));
        }
      }
    }
    return {
      det: detAcc.toString(),
      rref: M.map(r => r.map(v => v.toString()))
    };
  };
})();
