def solveNQueens(n):
    def is_safe(board, row, col):
        for i in range(row):
            if board[i] == col or abs(board[i] - col) == row - i:
                return False
        return True

    def solve_n_queens_util(row, board, solutions):
        if row == n:
            solution = ["." * i + "Q" + "." * (n - i - 1) for i in board]
            solutions.append(solution)
            return

        for col in range(n):
            if is_safe(board, row, col):
                board[row] = col
                solve_n_queens_util(row + 1, board, solutions)

    solutions = []
    board = [0] * n
    solve_n_queens_util(0, board, solutions)
    return solutions
