def make_palindrome(string: str) -> str:
    n = len(string)
    longest_palindrome_suffix_len = 0
    for i in range(n):
        suffix = string[i:]
        is_palindrome = True
        for j in range(len(suffix) // 2):
            if suffix[j] != suffix[len(suffix) - 1 - j]:
                is_palindrome = False
                break
        if is_palindrome:
            longest_palindrome_suffix_len = len(suffix)

    prefix = string[:n - longest_palindrome_suffix_len]
    reversed_prefix = ""
    for i in range(len(prefix) - 1, -1, -1):
        reversed_prefix += prefix[i]

    return string + reversed_prefix
