def fibonacci_prime_factors(n):
    fib_sequence = [0, 1]
    while len(fib_sequence) < n:
        next_fib = fib_sequence[-1] + fib_sequence[-2]
        fib_sequence.append(next_fib)

    for num in fib_sequence:
        factors = []
        if num == 0:
            print(f"{num} []")
            continue
        if num == 1:
            print(f"{num} []")
            continue

        d = 2
        temp_num = num
        while d * d <= temp_num:
            exponent = 0
            while temp_num % d == 0:
                exponent += 1
                temp_num //= d
            if exponent > 0:
                factors.append((d, exponent))
            d += 1
        if temp_num > 1:
            factors.append((temp_num, 1))

        print(f"{num} {factors}")

