import ast

def flatten_dict(nested_dict):
    flattened = {}
    def recurse(d, parent_key=''):
        for k, v in d.items():
            new_key = parent_key + '.' + k if parent_key else k
            if isinstance(v, dict):
                recurse(v, new_key)
            else:
                flattened[new_key] = v
    recurse(nested_dict)
    return flattened

if __name__ == "__main__":
