import json
import datetime

posts = {}
next_id = 1

def create_post(title, content, author):
    global next_id
    date = datetime.datetime.utcnow().isoformat()
    post = {"id": next_id, "title": title, "content": content, "author": author, "date": date}
    posts[next_id] = post
    next_id += 1
    return post

def read_post(id):
    return posts.get(id, {})

def update_post(id, title, content, author):
    if id in posts:
        posts[id]["title"] = title
        posts[id]["content"] = content
        posts[id]["author"] = author
        posts[id]["date"] = datetime.datetime.utcnow().isoformat()
        return posts[id]
    return {}

def delete_post(id):
    if id in posts:
        del posts[id]
    return {}

def read_all_posts():
    return list(posts.values())

n = int(input())
for _ in range(n):
    command = input().split()
    if command[0] == "CREATE":
        title = command[1]
        content = command[2]
        author = command[3]
        post = create_post(title, content, author)
        print(json.dumps(post))
    elif command[0] == "READALL":
        print(json.dumps(read_all_posts()))
    elif command[0] == "READ":
        id = int(command[1])
        print(json.dumps(read_post(id)))
    elif command[0] == "UPDATE":
        id = int(command[1])
        title = command[2]
        content = command[3]
        author = command[4]
        print(json.dumps(update_post(id, title, content, author)))
    elif command[0] == "DELETE":
        id = int(command[1])
        print(json.dumps(delete_post(id)))
